// The storage behind a FIFO: a block of DEPTH words, one write port
// and one read port, both synchronous to clk.
//
// The ports are the contract. Milestone 2 instantiates this module by
// exactly these names, so changing one breaks the next milestone.

module fifo_mem #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 4
) (
    input  logic                    clk,

    input  logic                    we,       // write enable
    input  logic [$clog2(DEPTH)-1:0] waddr,
    input  logic [WIDTH-1:0]        wdata,

    input  logic [$clog2(DEPTH)-1:0] raddr,
    output logic [WIDTH-1:0]        rdata     // one cycle after raddr
);

    // your code here — a block of DEPTH words of WIDTH bits, written
    // on a rising edge when we is high, and read on EVERY rising edge
    // into rdata. A read of the address being written in the same
    // cycle sees the OLD contents.

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench for the storage. Submit uses another one that
// drives a different width and depth and fills every address.
module tb;

  localparam int W = 8;
  localparam int D = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic           we    = 1'b0;
  logic [1:0]     waddr = 2'd0;
  logic [1:0]     raddr = 2'd0;
  logic [W-1:0]   wdata = '0;
  logic [W-1:0]   rdata;

  fifo_mem #(.WIDTH(W), .DEPTH(D)) dut (
    .clk(clk), .we(we), .waddr(waddr), .wdata(wdata),
    .raddr(raddr), .rdata(rdata)
  );

  logic [W-1:0] got0, got1, before1, collide, after;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // Two writes, on consecutive edges.
    @(negedge clk); we = 1'b1; waddr = 2'd0; wdata = 8'hA1;
    @(negedge clk);            waddr = 2'd1; wdata = 8'hB2;
    @(negedge clk); we = 1'b0;

    // Present address 0. One rising edge later it is on rdata.
    raddr = 2'd0;
    @(posedge clk); #1; got0 = rdata;

    // Latency: change the address and look BEFORE the next edge. The
    // old word is still there, because the read is registered.
    @(negedge clk); raddr = 2'd1;
    #1; before1 = rdata;
    @(posedge clk); #1; got1 = rdata;

    // Read and write the same address on one edge: the old word comes
    // out, and the new one is in the array afterwards.
    @(negedge clk); raddr = 2'd0; we = 1'b1; waddr = 2'd0; wdata = 8'hC3;
    @(posedge clk); #1; collide = rdata;
    @(negedge clk); we = 1'b0;
    @(posedge clk); #1; after = rdata;

    $display("CHECK read_back_0 161 %0d AT %0d", got0, $time);
    $display("CHECK read_latency_one 161 %0d AT %0d", before1, $time);
    $display("CHECK read_back_1 178 %0d AT %0d", got1, $time);
    $display("CHECK old_word_on_collision 161 %0d AT %0d", collide, $time);
    $display("CHECK new_word_is_stored 195 %0d AT %0d", after, $time);
    $display("DONE 5");
    $finish;
  end

endmodule
